export default function Breadcrumb() {
  const items = ['{{crumb_one}}', '{{crumb_two}}', '{{crumb_three}}'];
  return (
    <nav className="text-sm text-gray-500">
      {items.map((c, i) => (
        <span key={c}>
          <a href="#" className="hover:text-gray-900">{c}</a>
          {i < items.length - 1 && <span className="mx-2">/</span>}
        </span>
      ))}
    </nav>
  );
}
